21	/**
22	 * Resolves an owner's locality (canonical region). The postcode is preferred: a postcode
23	 * falling in a known region's range fixes the region directly, which disambiguates cities
24	 * that share a name. Only when the postcode is absent or in no known range does resolution
25	 * fall back to the fixed city-to-region table; cities absent from that table (and postcodes
26	 * in no known range) resolve to {@link #UNKNOWN}.
27	 */
28	public abstract class LocalityResolver {
29	
30	    /** Locality returned when neither the postcode nor the city resolves to a region. */
31	    public static final String UNKNOWN = "UNKNOWN";
32	
33	    /** City -> canonical region. */
34	    private static final Map<String, String> CITY_REGION =
35	        Map.of("Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
36	
37	    /** Region -> inclusive 4-digit postcode range {low, high}. */
38	    private static final Map<String, int[]> REGION_RANGE = Map.of(
39	        "NSW", new int[] {2000, 2099},
40	        "VIC", new int[] {3000, 3099},
41	        "QLD", new int[] {4000, 4099});
42	
43	    /**
44	     * Return the canonical region for the given postcode and city, preferring the postcode:
45	     * a postcode within a known region's range yields that region, otherwise the city-to-region
46	     * table is consulted. Yields {@link #UNKNOWN} when neither resolves to a region.
47	     */
48	    public static String localityOf(String postcode, String city) {
49	        String byPostcode = regionForPostcode(postcode);
50	        if (byPostcode != null) {
51	            return byPostcode;
52	        }
53	        return CITY_REGION.getOrDefault(city, UNKNOWN);
54	    }
55	
56	    /**
57	     * Return the canonical region for the given city alone (no postcode), or {@link #UNKNOWN}
58	     * when the city is {@code null} or not in the table.
59	     */
60	    public static String localityOf(String city) {
61	        return localityOf(null, city);
62	    }
63	
64	    /**
65	     * Return the region whose range contains the given postcode, or {@code null} when the
66	     * postcode is {@code null}, non-numeric, or in no known region's range.
67	     */
68	    private static String regionForPostcode(String postcode) {
69	        if (postcode == null) {
70	            return null;
71	        }
72	        int value;
73	        try {
74	            value = Integer.parseInt(postcode.trim());
75	        }
76	        catch (NumberFormatException e) {
77	            return null;
78	        }
79	        for (Map.Entry<String, int[]> entry : REGION_RANGE.entrySet()) {
80	            int[] range = entry.getValue();
81	            if (value >= range[0] && value <= range[1]) {
82	                return entry.getKey();
83	            }
84	        }
85	        return null;
86	    }
87	
88	    /**
89	     * Return the inclusive {@code {low, high}} postcode range for the given region, or
90	     * {@code null} when the region is unknown. A defensive copy is returned so callers
91	     * cannot mutate the shared table.
92	     */
93	    public static int[] rangeForRegion(String region) {
94	        int[] range = REGION_RANGE.get(region);
95	        return range == null ? null : range.clone();
96	    }
