1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.data.domain.Page;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
11	import org.springframework.samples.petclinic.rest.CustomerCodeGenerator;
12	import org.springframework.samples.petclinic.util.AgeBandResolver;
13	import org.springframework.samples.petclinic.util.FiscalYearResolver;
14	import org.springframework.samples.petclinic.util.IdentityKey;
15	import org.springframework.samples.petclinic.util.LuhnCheckDigit;
16	import org.springframework.samples.petclinic.util.MembershipLevelCalculator;
17	import org.springframework.samples.petclinic.util.MembershipNumberFormatter;
18	import org.springframework.samples.petclinic.util.TelephoneDisplayFormatter;
19	import org.springframework.samples.petclinic.util.TimezoneResolver;
20	
21	import java.util.Collection;
22	import java.util.List;
23	
24	/**
25	 * Maps Owner & OwnerDto using Mapstruct
26	 */
27	@Mapper(uses = PetMapper.class)
28	public interface OwnerMapper {
29	
30	    @Mapping(target = "selfLink", expression = "java(formatSelfLink(owner))")
31	    @Mapping(target = "displayName", expression = "java(formatDisplayName(owner))")
32	    @Mapping(target = "initials", expression = "java(formatInitials(owner))")
33	    @Mapping(target = "salutation", expression = "java(formatSalutation(owner))")
34	    @Mapping(target = "telephoneDisplay", expression = "java(formatTelephoneDisplay(owner))")
35	    @Mapping(target = "checkDigit", expression = "java(computeCheckDigit(owner))")
36	    @Mapping(target = "membershipNumber", expression = "java(formatMembershipNumber(owner))")
37	    @Mapping(target = "fiscalYear", expression = "java(formatFiscalYear(owner))")
38	    @Mapping(target = "membershipPoints", expression = "java(computeMembershipPoints(owner))")
39	    @Mapping(target = "membershipLevel", expression = "java(computeMembershipLevel(owner))")
40	    @Mapping(target = "locality", expression = "java(formatLocality(owner))")
41	    @Mapping(target = "timezone", expression = "java(formatTimezone(owner))")
42	    @Mapping(target = "contactPreference", expression = "java(formatContactPreference(owner))")
43	    @Mapping(target = "identityKey", expression = "java(formatIdentityKey(owner))")
44	    @Mapping(target = "ageBand", expression = "java(formatAgeBand(owner))")
45	    @Mapping(target = "sharesHousehold", ignore = true)
46	    OwnerDto toOwnerDto(Owner owner);
47	
48	    /**
49	     * Builds an owner's canonical self link from its id, formatted
50	     * {@code "/api/owners/<id>"}. Returns {@code null} when the owner has no id yet.
51	     */
52	    default String formatSelfLink(Owner owner) {
53	        if (owner.getId() == null) {
54	            return null;
55	        }
56	        return "/api/owners/" + owner.getId();
57	    }
58	
59	    /**
60	     * Builds an owner's display name from the stored names, formatted as
61	     * {@code "LastName, FirstName"}.
62	     */
63	    default String formatDisplayName(Owner owner) {
64	        return owner.getLastName() + ", " + owner.getFirstName();
65	    }
66	
67	    /**
68	     * Builds an owner's salutation from the stored title and last name: the title
69	     * followed by a single space and the last name when a title is present, or just
70	     * the last name when no title is given.
71	     */
72	    default String formatSalutation(Owner owner) {
73	        String title = owner.getTitle();
74	        if (title == null || title.isBlank()) {
75	            return owner.getLastName();
76	        }
77	        return title + " " + owner.getLastName();
78	    }
79	
80	    /**
81	     * Builds an owner's initials from the stored names as the upper-cased first
82	     * letters of the first and last name, dot-separated with a trailing dot,
83	     * e.g. {@code "J.S."}.
84	     */
85	    default String formatInitials(Owner owner) {
86	        return Character.toUpperCase(owner.getFirstName().charAt(0)) + "."
87	            + Character.toUpperCase(owner.getLastName().charAt(0)) + ".";
88	    }
89	
90	    /**
91	     * Formats an owner's stored E.164 telephone for humans, delegating to
92	     * {@link TelephoneDisplayFormatter}. The raw {@code telephone} stays in E.164 form.
93	     */
94	    default String formatTelephoneDisplay(Owner owner) {
95	        return TelephoneDisplayFormatter.display(owner.getTelephone());
96	    }
97	
98	    /**
99	     * Builds an owner's membership number from its stored fields, formatted
100	     * {@code '<customerCode>-M<YY>'} where {@code YY} is the last two digits of
101	     * the registration date's year, e.g. {@code "NSW-3F2A9C1E-M26"}. Returns
102	     * {@code null} when either the customer code or registration date is absent.
103	     */
104	    default String formatMembershipNumber(Owner owner) {
105	        return MembershipNumberFormatter.membershipNumber(owner);
106	    }
107	
108	    /**
109	     * Derives an owner's fiscal year from its (business-day-adjusted) registration date,
110	     * delegating to {@link FiscalYearResolver}. Returns {@code null} when no registration
111	     * date is present.
112	     */
113	    default String formatFiscalYear(Owner owner) {
114	        return FiscalYearResolver.label(owner.getRegistrationDate());
115	    }
116	
117	    /**
118	     * Computes an owner's check digit from its stored customer code, delegating to
